66	  const [isFeatured, setIsFeatured] = useState(false);
67	  const [saving, setSaving] = useState(false);
68	  // loaded tracks whether DB data has been fetched — blocks form render until then
69	  // to prevent user input being silently overwritten by the async load.
70	  const [loaded, setLoaded] = useState(false);
71	
72	  useEffect(() => {
73	    // Reset loaded state when job changes so we don't show stale data
74	    setLoaded(false);
75	    setLocation("");
76	    setDepartment("");
77	    setEmploymentType("Full-time");
78	    setSalaryRange("");
79	    setExpiresAt("");
80	    setIsFeatured(false);
81	
82	    let cancelled = false;
83	    (async () => {
84	      const { data } = await (supabase as any)
85	        .from("jobs")
86	        .select("location, department, employment_type, salary_range, expires_at, is_featured")
87	        .eq("id", jobId)
88	        .single();
89	      if (!cancelled) {
90	        setLocation(data?.location ?? "");
91	        setDepartment(data?.department ?? "");
92	        setEmploymentType(data?.employment_type ?? "Full-time");
93	        setSalaryRange(data?.salary_range ?? "");
94	        setExpiresAt(data?.expires_at ? new Date(data.expires_at).toISOString().split("T")[0] : "");
95	        setIsFeatured(data?.is_featured ?? false);
96	        setLoaded(true);
97	      }
98	    })();
99	    return () => { cancelled = true; };
