import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage } from "../_shared/logError.ts";

// Public endpoint — no JWT required. Uses service role to bypass RLS.
// GET  ?token=...             → available slots for next 14 days
// POST { token, selected_time } → confirm booking

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsHeaders(req: Request) {
  const origin = req.headers.get("origin") || "";
  const allowedOrigin = ALLOWED_ORIGINS.includes(origin) ? origin : "*";
  return {
    "Access-Control-Allow-Origin": allowedOrigin,
    "Access-Control-Allow-Headers": "content-type",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  };
}

function json(data: unknown, status = 200, extra: HeadersInit = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...extra },
  });
}

// Generate candidate available time slots for a given date
// based on interviewer's weekly availability minus existing interviews.
function generateSlots(
  daySlot: { start_time: string; end_time: string; timezone: string },
  durationMinutes: number,
  date: Date,
  existingInterviews: Array<{ scheduled_at: string; duration_minutes: number }>
): string[] {
  const [sh, sm] = daySlot.start_time.split(":").map(Number);
  const [eh, em] = daySlot.end_time.split(":").map(Number);

  const startMinutes = sh * 60 + sm;
  const endMinutes = eh * 60 + em;

  const slots: string[] = [];
  for (let min = startMinutes; min + durationMinutes <= endMinutes; min += 30) {
    const slotDate = new Date(date);
    slotDate.setUTCHours(Math.floor(min / 60), min % 60, 0, 0);

    // Skip past slots
    if (slotDate <= new Date()) continue;

    // Check for conflicts with existing interviews
    const hasConflict = existingInterviews.some((iv) => {
      const ivStart = new Date(iv.scheduled_at).getTime();
      const ivEnd = ivStart + iv.duration_minutes * 60_000;
      const slotStart = slotDate.getTime();
      const slotEnd = slotStart + durationMinutes * 60_000;
      return slotStart < ivEnd && slotEnd > ivStart;
    });

    if (!hasConflict) {
      slots.push(slotDate.toISOString());
    }
  }

  return slots;
}

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);

  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    if (req.method === "GET") {
      // ── GET: Return available slots for the next 14 days ────────────
      const url = new URL(req.url);
      const token = url.searchParams.get("token");

      if (!token) {
        return json({ error: "Missing token parameter" }, 400, corsHeaders);
      }

      // Fetch token record
      const { data: tokenRecord, error: tokenError } = await supabase
        .from("booking_tokens")
        .select("id, job_id, resume_id, interviewer_id, duration_minutes, expires_at, used")
        .eq("token", token)
        .single();

      if (tokenError || !tokenRecord) {
        return json({ error: "Invalid or expired booking link" }, 404, corsHeaders);
      }

      if (tokenRecord.used) {
        return json({ error: "This booking link has already been used" }, 410, corsHeaders);
      }

      if (new Date(tokenRecord.expires_at) < new Date()) {
        return json({ error: "This booking link has expired" }, 410, corsHeaders);
      }

      // Fetch job title and resume details
      const [jobRes, resumeRes] = await Promise.all([
        supabase.from("jobs").select("title").eq("id", tokenRecord.job_id).single(),
        supabase.from("resumes").select("candidate_name, filename").eq("id", tokenRecord.resume_id).single(),
      ]);

      // Fetch interviewer's availability slots
      const { data: availabilitySlots } = await supabase
        .from("availability_slots")
        .select("day_of_week, start_time, end_time, timezone")
        .eq("user_id", tokenRecord.interviewer_id)
        .eq("is_active", true);

      if (!availabilitySlots || availabilitySlots.length === 0) {
        return json({
          job_title: jobRes.data?.title ?? "Open Position",
          candidate_name: resumeRes.data?.candidate_name || resumeRes.data?.filename || "Candidate",
          duration_minutes: tokenRecord.duration_minutes,
          slots: [],
          message: "No available time slots configured for this interviewer",
        }, 200, corsHeaders);
      }

      // Build a map of day_of_week → availability
      const availMap = new Map<number, { start_time: string; end_time: string; timezone: string }>();
      for (const slot of availabilitySlots) {
        availMap.set(slot.day_of_week, slot);
      }

      // Fetch existing interviews for the interviewer in the next 14 days
      const lookAheadEnd = new Date();
      lookAheadEnd.setDate(lookAheadEnd.getDate() + 14);

      const { data: existingInterviews } = await supabase
        .from("interviews")
        .select("scheduled_at, duration_minutes")
        .eq("interviewer_id", tokenRecord.interviewer_id)
        .in("status", ["scheduled"])
        .gte("scheduled_at", new Date().toISOString())
        .lte("scheduled_at", lookAheadEnd.toISOString());

      // Generate slots for next 14 days
      const allSlots: string[] = [];
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      for (let d = 0; d < 14; d++) {
        const date = new Date(today);
        date.setDate(date.getDate() + d);
        const dow = date.getDay(); // 0=Sun

        const dayAvail = availMap.get(dow);
        if (!dayAvail) continue;

        const daySlots = generateSlots(
          dayAvail,
          tokenRecord.duration_minutes,
          date,
          existingInterviews ?? []
        );
        allSlots.push(...daySlots);
      }

      return json({
        job_title: jobRes.data?.title ?? "Open Position",
        candidate_name: resumeRes.data?.candidate_name || resumeRes.data?.filename || "Candidate",
        duration_minutes: tokenRecord.duration_minutes,
        slots: allSlots,
      }, 200, corsHeaders);

    } else if (req.method === "POST") {
      // ── POST: Confirm booking ────────────────────────────────────────
      const body = await req.json();
      const { token, selected_time, candidate_name, candidate_email } = body as {
        token: string;
        selected_time: string;
        candidate_name?: string;
        candidate_email?: string;
      };

      if (!token || !selected_time) {
        return json({ error: "Missing token or selected_time" }, 400, corsHeaders);
      }

      // Re-fetch token with FOR UPDATE semantics via service role
      const { data: tokenRecord, error: tokenError } = await supabase
        .from("booking_tokens")
        .select("id, job_id, resume_id, interviewer_id, duration_minutes, expires_at, used")
        .eq("token", token)
        .single();

      if (tokenError || !tokenRecord) {
        return json({ error: "Invalid booking link" }, 404, corsHeaders);
      }

      if (tokenRecord.used) {
        return json({ error: "This booking link has already been used" }, 410, corsHeaders);
      }

      if (new Date(tokenRecord.expires_at) < new Date()) {
        return json({ error: "This booking link has expired" }, 410, corsHeaders);
      }

      // Validate selected time is in the future
      const selectedDate = new Date(selected_time);
      if (selectedDate <= new Date()) {
        return json({ error: "Selected time is in the past" }, 400, corsHeaders);
      }

      // Fetch candidate info from resume if not provided
      const { data: resumeData } = await supabase
        .from("resumes")
        .select("candidate_name, filename")
        .eq("id", tokenRecord.resume_id)
        .single();

      const finalCandidateName = candidate_name || resumeData?.candidate_name || resumeData?.filename || "Candidate";

      // Create interview record
      const { data: interview, error: insertError } = await supabase
        .from("interviews")
        .insert({
          job_id: tokenRecord.job_id,
          resume_id: tokenRecord.resume_id,
          interviewer_id: tokenRecord.interviewer_id,
          candidate_name: finalCandidateName,
          candidate_email: candidate_email || null,
          scheduled_at: selectedDate.toISOString(),
          duration_minutes: tokenRecord.duration_minutes,
          status: "scheduled",
        })
        .select("id")
        .single();

      if (insertError || !interview) {
        console.error("Failed to create interview:", insertError?.message);
        return json({ error: "Failed to schedule interview. Please try again." }, 500, corsHeaders);
      }

      // Mark token as used
      await supabase
        .from("booking_tokens")
        .update({ used: true })
        .eq("id", tokenRecord.id);

      // Send confirmation email if platform email is configured
      try {
        const { data: platformConfig } = await supabase
          .from("platform_config")
          .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
          .limit(1)
          .single();

        const { data: jobData } = await supabase
          .from("jobs")
          .select("title")
          .eq("id", tokenRecord.job_id)
          .single();

        if (platformConfig?.outbound_email_enabled && platformConfig?.resend_api_key && candidate_email) {
          const formattedDate = new Date(selected_time).toLocaleString("en-US", {
            weekday: "long",
            year: "numeric",
            month: "long",
            day: "numeric",
            hour: "2-digit",
            minute: "2-digit",
            timeZoneName: "short",
          });

          await fetch("https://api.resend.com/emails", {
            method: "POST",
            headers: {
              Authorization: `Bearer ${platformConfig.resend_api_key}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              from: `${platformConfig.email_from_name || "Rankora"} <${platformConfig.email_from_address || "noreply@rankora.co"}>`,
              to: [candidate_email],
              subject: `Interview Confirmed – ${jobData?.title ?? "Position"}`,
              html: `<p>Hi ${finalCandidateName},</p>
<p>Your interview has been scheduled for <strong>${formattedDate}</strong>.</p>
<p>Duration: ${tokenRecord.duration_minutes} minutes</p>
<p>We look forward to speaking with you!</p>
<p>Best regards</p>`,
            }),
          });
        }
      } catch (emailErr) {
        // Don't fail the booking if email fails
        console.error("Confirmation email failed:", emailErr);
      }

      return json({
        success: true,
        interview_id: interview.id,
        scheduled_at: selectedDate.toISOString(),
      }, 200, corsHeaders);

    } else {
      return json({ error: "Method not allowed" }, 405, corsHeaders);
    }
  } catch (err: unknown) {
    console.error("book-interview error:", err);
    await logSystemError({
      function_name: "book-interview",
      error_type: "BOOKING_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
    });
    return json({ error: "Internal server error" }, 500, corsHeaders);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { errorToMessage } from "../_shared/logError.ts";

// Public endpoint — no auth required.
// GET ?team_id=...  → Indeed XML feed for the team's published jobs
// GET ?user_id=...  → Fallback: user's own published jobs

serve(async (req) => {
  const CORS_HEADERS = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, OPTIONS",
  };

  if (req.method === "OPTIONS") {
    return new Response(null, { headers: CORS_HEADERS });
  }

  if (req.method !== "GET") {
    return new Response("Method not allowed", { status: 405, headers: CORS_HEADERS });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const APP_URL = Deno.env.get("APP_URL") || "https://rankora.co";

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    const url = new URL(req.url);
    const teamId = url.searchParams.get("team_id");
    const userId = url.searchParams.get("user_id");

    if (!teamId && !userId) {
      return new Response("Missing team_id or user_id parameter", {
        status: 400,
        headers: { ...CORS_HEADERS, "Content-Type": "text/plain" },
      });
    }

    // Fetch career page config for company name + slug
    let careerConfig: { company_name: string; slug: string } | null = null;
    if (teamId) {
      const { data } = await supabase
        .from("career_page_config")
        .select("company_name, slug")
        .eq("team_id", teamId)
        .eq("is_active", true)
        .single();
      careerConfig = data;
    } else if (userId) {
      const { data } = await supabase
        .from("career_page_config")
        .select("company_name, slug")
        .eq("user_id", userId)
        .eq("is_active", true)
        .single();
      careerConfig = data;
    }

    // Fetch published, non-expired jobs
    let jobsQuery = supabase
      .from("jobs")
      .select("id, title, job_description, location, department, employment_type, salary_range, created_at")
      .eq("is_published", true)
      .or("expires_at.is.null,expires_at.gt." + new Date().toISOString());

    if (teamId) {
      jobsQuery = jobsQuery.eq("team_id", teamId);
    } else if (userId) {
      jobsQuery = jobsQuery.eq("user_id", userId);
    }

    const { data: jobs, error: jobsError } = await jobsQuery.order("created_at", { ascending: false });

    if (jobsError) throw new Error(jobsError.message);

    const now = new Date();
    const buildDateStr = now.toUTCString();
    const companyName = careerConfig?.company_name ?? "Company";
    const slug = careerConfig?.slug ?? "";

    // Map employment type to Indeed's expected values
    function mapEmploymentType(type: string | null): string {
      if (!type) return "fulltime";
      const t = type.toLowerCase();
      if (t.includes("part")) return "parttime";
      if (t.includes("contract")) return "contract";
      if (t.includes("intern")) return "internship";
      if (t.includes("freelance")) return "contract";
      return "fulltime";
    }

    function xmlEscape(str: string | null | undefined): string {
      if (!str) return "";
      return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&apos;");
    }

    function formatDate(iso: string): string {
      return new Date(iso).toUTCString().replace(" GMT", "");
    }

    const jobItems = (jobs ?? [])
      .map((job) => {
        const jobUrl = slug
          ? `${APP_URL}/careers/${slug}/jobs/${job.id}`
          : `${APP_URL}`;

        // Parse location into city/state/country best-effort
        let city = "";
        let state = "";
        let country = "US";
        if (job.location) {
          const parts = job.location.split(",").map((s: string) => s.trim());
          if (parts.length >= 2) {
            city = parts[0];
            // Handle "CA" vs "California" vs "CA, US"
            const stateParts = parts[1].split(" ").filter(Boolean);
            state = stateParts[0] ?? "";
            if (stateParts[1]) country = stateParts[1];
          } else if (parts.length === 1) {
            city = parts[0];
          }
          if (job.location.toLowerCase().includes("remote")) {
            city = "Remote";
          }
        }

        return `  <job>
    <title><![CDATA[${xmlEscape(job.title)}]]></title>
    <date>${formatDate(job.created_at)}</date>
    <referencenumber>${job.id}</referencenumber>
    <url>${xmlEscape(jobUrl)}</url>
    <company><![CDATA[${xmlEscape(companyName)}]]></company>${city ? `\n    <city><![CDATA[${xmlEscape(city)}]]></city>` : ""}${state ? `\n    <state>${xmlEscape(state)}</state>` : ""}
    <country>${xmlEscape(country)}</country>
    <description><![CDATA[${xmlEscape(job.job_description ?? "")}]]></description>${job.salary_range ? `\n    <salary><![CDATA[${xmlEscape(job.salary_range)}]]></salary>` : ""}
    <jobtype>${mapEmploymentType(job.employment_type)}</jobtype>
  </job>`;
      })
      .join("\n");

    const xml = `<?xml version="1.0" encoding="UTF-8"?>
<source>
  <publisher>${xmlEscape(companyName)}</publisher>
  <publisherurl>${APP_URL}</publisherurl>
  <lastBuildDate>${buildDateStr}</lastBuildDate>
${jobItems}
</source>`;

    return new Response(xml, {
      status: 200,
      headers: {
        ...CORS_HEADERS,
        "Content-Type": "application/xml; charset=utf-8",
        "Cache-Control": "public, max-age=3600",
      },
    });
  } catch (err: unknown) {
    console.error("indeed-feed error:", errorToMessage(err));
    return new Response(`<?xml version="1.0" encoding="UTF-8"?><source><error>${errorToMessage(err)}</error></source>`, {
      status: 500,
      headers: { ...CORS_HEADERS, "Content-Type": "application/xml" },
    });
  }
});

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { Clock, Loader2, Save } from "lucide-react";

interface AvailabilitySettingsProps {
  userId: string;
  teamId?: string | null;
}

interface DaySlot {
  day_of_week: number;
  is_active: boolean;
  start_time: string;
  end_time: string;
  timezone: string;
}

const DAYS = [
  { label: "Sunday", short: "Sun", value: 0 },
  { label: "Monday", short: "Mon", value: 1 },
  { label: "Tuesday", short: "Tue", value: 2 },
  { label: "Wednesday", short: "Wed", value: 3 },
  { label: "Thursday", short: "Thu", value: 4 },
  { label: "Friday", short: "Fri", value: 5 },
  { label: "Saturday", short: "Sat", value: 6 },
];

const COMMON_TIMEZONES = [
  "UTC",
  "America/New_York",
  "America/Chicago",
  "America/Denver",
  "America/Los_Angeles",
  "America/Toronto",
  "America/Vancouver",
  "Europe/London",
  "Europe/Paris",
  "Europe/Berlin",
  "Asia/Kolkata",
  "Asia/Singapore",
  "Asia/Tokyo",
  "Australia/Sydney",
  "Pacific/Auckland",
];

function makeDefaultSlots(): DaySlot[] {
  return DAYS.map((d) => ({
    day_of_week: d.value,
    is_active: d.value >= 1 && d.value <= 5, // Mon–Fri default active
    start_time: "09:00",
    end_time: "17:00",
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC",
  }));
}

function generateTimeOptions(): { value: string; label: string }[] {
  const options: { value: string; label: string }[] = [];
  for (let h = 0; h < 24; h++) {
    for (const m of [0, 30]) {
      const hh = String(h).padStart(2, "0");
      const mm = String(m).padStart(2, "0");
      const value = `${hh}:${mm}`;
      const hour12 = h === 0 ? 12 : h > 12 ? h - 12 : h;
      const ampm = h < 12 ? "AM" : "PM";
      const label = `${hour12}:${mm} ${ampm}`;
      options.push({ value, label });
    }
  }
  return options;
}

const TIME_OPTIONS = generateTimeOptions();

const AvailabilitySettings = ({ userId, teamId }: AvailabilitySettingsProps) => {
  const queryClient = useQueryClient();
  const [slots, setSlots] = useState<DaySlot[]>(makeDefaultSlots);
  const [timezone, setTimezone] = useState<string>(
    Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"
  );

  // Fetch existing availability
  const { data: existingSlots, isLoading } = useQuery({
    queryKey: ["availability_slots", userId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("availability_slots")
        .select("day_of_week, is_active, start_time, end_time, timezone")
        .eq("user_id", userId)
        .order("day_of_week");
      if (error) throw error;
      return (data ?? []) as DaySlot[];
    },
    enabled: !!userId,
  });

  // Populate form once data loads
  useEffect(() => {
    if (!existingSlots) return;
    if (existingSlots.length === 0) return;

    const tz = existingSlots[0].timezone || "UTC";
    setTimezone(tz);

    const merged = makeDefaultSlots().map((def) => {
      const found = existingSlots.find((s) => s.day_of_week === def.day_of_week);
      return found ? { ...found } : def;
    });
    setSlots(merged);
  }, [existingSlots]);

  // Save mutation — upsert all 7 rows
  const saveMutation = useMutation({
    mutationFn: async () => {
      // Delete existing for this user then re-insert (simpler than per-row upsert)
      const { error: delError } = await (supabase as any)
        .from("availability_slots")
        .delete()
        .eq("user_id", userId);
      if (delError) throw delError;

      const rows = slots.map((s) => ({
        user_id: userId,
        team_id: teamId || null,
        day_of_week: s.day_of_week,
        is_active: s.is_active,
        start_time: s.start_time,
        end_time: s.end_time,
        timezone,
      }));

      const { error: insertError } = await (supabase as any)
        .from("availability_slots")
        .insert(rows);
      if (insertError) throw insertError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["availability_slots", userId] });
      toast.success("Availability saved");
    },
    onError: () => {
      toast.error("Failed to save availability");
    },
  });

  const updateSlot = (dayOfWeek: number, field: keyof DaySlot, value: string | boolean) => {
    setSlots((prev) =>
      prev.map((s) =>
        s.day_of_week === dayOfWeek ? { ...s, [field]: value } : s
      )
    );
  };

  if (isLoading) {
    return (
      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <Skeleton className="h-5 w-48" />
          <Skeleton className="h-4 w-72" />
        </CardHeader>
        <CardContent className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <Skeleton key={i} className="h-10 w-full" />
          ))}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-4">
        <CardTitle className="flex items-center gap-2 text-sm font-semibold">
          <Clock className="h-4 w-4 text-primary" />
          Interview Availability
        </CardTitle>
        <CardDescription>
          Set your weekly availability so candidates can book interview slots.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Timezone selector */}
        <div className="flex items-center gap-3">
          <Label className="text-xs text-muted-foreground shrink-0 w-20">Timezone</Label>
          <Select value={timezone} onValueChange={setTimezone}>
            <SelectTrigger className="h-8 text-xs max-w-[260px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {COMMON_TIMEZONES.map((tz) => (
                <SelectItem key={tz} value={tz} className="text-xs">
                  {tz}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Weekly grid */}
        <div className="rounded-lg border border-border overflow-hidden">
          {/* Header */}
          <div className="grid grid-cols-[100px_60px_1fr_1fr] gap-0 bg-muted/50 px-3 py-2 border-b border-border">
            <span className="text-xs font-medium text-muted-foreground">Day</span>
            <span className="text-xs font-medium text-muted-foreground text-center">Active</span>
            <span className="text-xs font-medium text-muted-foreground pl-3">From</span>
            <span className="text-xs font-medium text-muted-foreground pl-3">To</span>
          </div>

          {slots.map((slot, idx) => {
            const day = DAYS[slot.day_of_week];
            const isLast = idx === slots.length - 1;
            return (
              <div
                key={slot.day_of_week}
                className={`grid grid-cols-[100px_60px_1fr_1fr] gap-0 items-center px-3 py-2 ${
                  !isLast ? "border-b border-border" : ""
                } ${!slot.is_active ? "opacity-50" : ""}`}
              >
                <span className="text-xs font-medium">{day.label}</span>

                <div className="flex justify-center">
                  <Switch
                    checked={slot.is_active}
                    onCheckedChange={(checked) =>
                      updateSlot(slot.day_of_week, "is_active", checked)
                    }
                    aria-label={`Toggle ${day.label}`}
                  />
                </div>

                <div className="pl-3">
                  <Select
                    value={slot.start_time}
                    onValueChange={(v) => updateSlot(slot.day_of_week, "start_time", v)}
                    disabled={!slot.is_active}
                  >
                    <SelectTrigger className="h-8 text-xs w-full max-w-[130px]">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="max-h-[200px]">
                      {TIME_OPTIONS.map((o) => (
                        <SelectItem key={o.value} value={o.value} className="text-xs">
                          {o.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="pl-3">
                  <Select
                    value={slot.end_time}
                    onValueChange={(v) => updateSlot(slot.day_of_week, "end_time", v)}
                    disabled={!slot.is_active}
                  >
                    <SelectTrigger className="h-8 text-xs w-full max-w-[130px]">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="max-h-[200px]">
                      {TIME_OPTIONS.filter((o) => o.value > slot.start_time).map((o) => (
                        <SelectItem key={o.value} value={o.value} className="text-xs">
                          {o.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
            );
          })}
        </div>

        <Button
          size="sm"
          className="gap-1.5"
          onClick={() => saveMutation.mutate()}
          disabled={saveMutation.isPending}
        >
          {saveMutation.isPending ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Save className="h-3.5 w-3.5" />
          )}
          Save Availability
        </Button>
      </CardContent>
    </Card>
  );
};

export default AvailabilitySettings;

