const DURATIONS = [
  { value: "15", label: "15 minutes" },
  { value: "30", label: "30 minutes" },
  { value: "45", label: "45 minutes" },
  { value: "60", label: "1 hour" },
];

// Generate next 14 days as selectable dates
function getDateOptions(): { value: string; label: string }[] {
  const options: { value: string; label: string }[] = [];
  const today = startOfDay(new Date());
  for (let i = 0; i < 14; i++) {
    const d = addDays(today, i);
    options.push({
      value: format(d, "yyyy-MM-dd"),
      label: format(d, "EEE, MMM d"),
    });
  }
  return options;
}

const DATE_OPTIONS = getDateOptions();

const ScheduleInterviewDialog = ({
  open,
  onOpenChange,
  jobId,
  resumeId,
  candidateName,
  candidateEmail,
}: ScheduleInterviewDialogProps) => {
  const { user } = useAuth();
  const { members, team } = useTeam();
  const queryClient = useQueryClient();

  const [interviewerId, setInterviewerId] = useState<string>(user?.id ?? "");
  const [selectedDate, setSelectedDate] = useState<string>(DATE_OPTIONS[0]?.value ?? "");
  const [selectedTime, setSelectedTime] = useState<string>("");
  const [duration, setDuration] = useState<string>("30");
  const [meetingLink, setMeetingLink] = useState<string>("");
  const [notes, setNotes] = useState<string>("");
  const [sendBookingLink, setSendBookingLink] = useState<boolean>(false);

  // Reset state when dialog opens
  useEffect(() => {
    if (open) {
      setInterviewerId(user?.id ?? "");
      setSelectedDate(DATE_OPTIONS[0]?.value ?? "");
      setSelectedTime("");
      setDuration("30");
      setMeetingLink("");
      setNotes("");
      setSendBookingLink(false);
    }
  }, [open, user?.id]);

  // Fetch available time slots for the selected interviewer + date
  const { data: availableSlots, isLoading: slotsLoading } = useQuery({
    queryKey: ["available_slots", interviewerId, selectedDate, duration],
    queryFn: async () => {
      if (!interviewerId || !selectedDate) return [];

      // Get interviewer availability for this day of week
      const date = new Date(selectedDate);
      const dow = date.getDay();

      const { data: avail } = await (supabase as any)
        .from("availability_slots")
        .select("start_time, end_time, timezone")
        .eq("user_id", interviewerId)
        .eq("day_of_week", dow)
        .eq("is_active", true)
        .single();

      if (!avail) return [];

      // Get existing interviews for that interviewer on that date
      const dayStart = new Date(selectedDate + "T00:00:00.000Z").toISOString();
      const dayEnd = new Date(selectedDate + "T23:59:59.999Z").toISOString();

      const { data: existing } = await (supabase as any)
        .from("interviews")
        .select("scheduled_at, duration_minutes")
        .eq("interviewer_id", interviewerId)
        .eq("status", "scheduled")
        .gte("scheduled_at", dayStart)
        .lte("scheduled_at", dayEnd);

      // Generate slots every 30 minutes within the window
      const [sh, sm] = avail.start_time.split(":").map(Number);
      const [eh, em] = avail.end_time.split(":").map(Number);
      const startMin = sh * 60 + sm;
      const endMin = eh * 60 + em;
      const durationMin = parseInt(duration, 10);
      const existingInterviews = existing ?? [];

      const slots: string[] = [];
      for (let min = startMin; min + durationMin <= endMin; min += 30) {
        // Build a UTC datetime for this slot
        const slotDate = new Date(`${selectedDate}T00:00:00.000Z`);
        slotDate.setUTCHours(Math.floor(min / 60), min % 60, 0, 0);

        // Skip past times
        if (slotDate <= new Date()) continue;

        // Check conflicts
        const hasConflict = existingInterviews.some((iv: { scheduled_at: string; duration_minutes: number }) => {
          const ivStart = new Date(iv.scheduled_at).getTime();
          const ivEnd = ivStart + iv.duration_minutes * 60_000;
          const slotStart = slotDate.getTime();
          const slotEnd = slotStart + durationMin * 60_000;
          return slotStart < ivEnd && slotEnd > ivStart;
        });

        if (!hasConflict) {
          slots.push(slotDate.toISOString());
        }
      }

      return slots;
    },
    enabled: !!interviewerId && !!selectedDate && open,
    staleTime: 30_000,
  });

  // Reset time selection when date/interviewer changes
  useEffect(() => {
    setSelectedTime("");
  }, [interviewerId, selectedDate]);

  // Schedule directly mutation
  const scheduleMutation = useMutation({
    mutationFn: async () => {
      if (!user) throw new Error("Not authenticated");
      if (!selectedTime) throw new Error("Please select a time slot");

      const { data, error } = await (supabase as any)
        .from("interviews")
        .insert({
          job_id: jobId,
          resume_id: resumeId,
          interviewer_id: interviewerId,
          candidate_name: candidateName,
          candidate_email: candidateEmail || null,
          scheduled_at: selectedTime,
          duration_minutes: parseInt(duration, 10),
          meeting_link: meetingLink.trim() || null,
          notes: notes.trim() || null,
          status: "scheduled",
        })
        .select("id")
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["interviews", resumeId] });
      toast.success("Interview scheduled");
      onOpenChange(false);
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to schedule interview");
    },
  });

  // Send booking link mutation
  const bookingLinkMutation = useMutation({
    mutationFn: async () => {
      if (!user) throw new Error("Not authenticated");

      // Create booking token
      const { data: tokenData, error: tokenError } = await (supabase as any)
        .from("booking_tokens")
        .insert({
          job_id: jobId,
          resume_id: resumeId,
          interviewer_id: interviewerId,
          duration_minutes: parseInt(duration, 10),
        })
        .select("token")
        .single();

      if (tokenError) throw tokenError;

      const bookingUrl = `${window.location.origin}/book/${tokenData.token}`;

      // Send the link via email
      if (candidateEmail) {
        const { data: emailData, error: emailError } = await supabase.functions.invoke("send-candidate-email", {
          body: {
            resume_id: resumeId,
            job_id: jobId,
            to_email: candidateEmail,
            subject: "Schedule Your Interview",
            body_html: `<p>Hi ${candidateName},</p>
<p>We'd like to schedule an interview with you! Please click the link below to choose a time that works for you:</p>
<p><a href="${bookingUrl}" style="background:#000;color:#fff;padding:10px 20px;border-radius:6px;text-decoration:none;display:inline-block;">Choose Your Interview Time</a></p>
<p>This link expires in 7 days.</p>
<p>Best regards</p>`,
          },
        });

        if (emailError) throw emailError;
        if (emailData?.skipped) {
          toast.warning("Booking link created but email is disabled. Copy the link manually.");
          return { token: tokenData.token, url: bookingUrl };
        }
      }

      return { token: tokenData.token, url: bookingUrl };
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["booking_tokens", resumeId] });
      if (candidateEmail) {
        toast.success("Booking link sent to candidate");
      } else {
        navigator.clipboard.writeText(data.url).catch(() => {});
        toast.success("Booking link copied to clipboard (no email on file)");
      }
      onOpenChange(false);
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to send booking link");
    },
  });

  const handleSubmit = () => {
    if (sendBookingLink) {
      bookingLinkMutation.mutate();
    } else {
      if (!selectedTime) {
        toast.error("Please select a time slot");
        return;
      }
      scheduleMutation.mutate();
    }
  };

  const isBusy = scheduleMutation.isPending || bookingLinkMutation.isPending;

  // Build interviewer options: current user + team members
  const interviewerOptions = [
    { id: user?.id ?? "", label: "Me" },
    ...members
      .filter((m) => m.user_id !== user?.id)
      .map((m) => ({
        id: m.user_id,
        label: m.email ? m.email : `Team member (${m.role})`,
      })),
  ].filter((o) => o.id);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Calendar className="h-4 w-4" />
            Schedule Interview — {candidateName}
          </DialogTitle>
        </DialogHeader>

        <ScrollArea className="max-h-[60vh] pr-1">
          <div className="space-y-4 py-2 pr-3">
            {/* Interviewer */}
            {interviewerOptions.length > 1 && (
              <div className="space-y-1.5">
                <Label className="text-xs">Interviewer</Label>
                <Select value={interviewerId} onValueChange={setInterviewerId}>
                  <SelectTrigger className="h-9 text-sm">
                    <SelectValue placeholder="Select interviewer" />
                  </SelectTrigger>
                  <SelectContent>
                    {interviewerOptions.map((o) => (
                      <SelectItem key={o.id} value={o.id} className="text-sm">
                        {o.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Duration */}
            <div className="space-y-1.5">
              <Label className="text-xs">Duration</Label>
              <Select value={duration} onValueChange={setDuration}>
                <SelectTrigger className="h-9 text-sm">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {DURATIONS.map((d) => (
                    <SelectItem key={d.value} value={d.value} className="text-sm">
                      {d.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Send booking link toggle */}
            <div className="flex items-center justify-between rounded-lg border border-border px-3 py-2.5">
              <div>
                <p className="text-sm font-medium">Send booking link to candidate</p>
                <p className="text-xs text-muted-foreground">
                  {candidateEmail
                    ? `Candidate picks their own slot from your availability`
                    : "No email on file — you'll get a link to share manually"}
                </p>
              </div>
              <Switch
                checked={sendBookingLink}
                onCheckedChange={setSendBookingLink}
                aria-label="Send booking link"
              />
            </div>

            {/* Direct scheduling fields (hidden when sending booking link) */}
            {!sendBookingLink && (
              <>
                {/* Date picker */}
                <div className="space-y-1.5">
                  <Label className="text-xs">Date</Label>
                  <Select value={selectedDate} onValueChange={setSelectedDate}>
                    <SelectTrigger className="h-9 text-sm">
                      <SelectValue placeholder="Select a date" />
                    </SelectTrigger>
                    <SelectContent>
                      {DATE_OPTIONS.map((d) => (
                        <SelectItem key={d.value} value={d.value} className="text-sm">
                          {d.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {/* Time slots */}
                <div className="space-y-1.5">
                  <Label className="text-xs">Available Time Slots</Label>
                  {slotsLoading ? (
                    <div className="grid grid-cols-3 gap-2">
                      {[1, 2, 3, 4, 5, 6].map((i) => (
                        <Skeleton key={i} className="h-9 rounded-md" />
                      ))}
                    </div>
                  ) : !availableSlots || availableSlots.length === 0 ? (
                    <div className="rounded-lg border border-border bg-muted/30 px-3 py-4 text-center">
                      <Clock className="h-5 w-5 text-muted-foreground/50 mx-auto mb-1" />
                      <p className="text-xs text-muted-foreground">
                        No availability set for this day. Configure availability in Settings.
                      </p>
                    </div>
                  ) : (
                    <div className="grid grid-cols-3 gap-2">
                      {availableSlots.map((slot) => {
                        const d = new Date(slot);
                        const timeLabel = d.toLocaleTimeString("en-US", {
                          hour: "2-digit",
                          minute: "2-digit",
                          hour12: true,
                        });
                        const isSelected = selectedTime === slot;
                        return (
                          <button
                            key={slot}
                            type="button"
                            onClick={() => setSelectedTime(slot)}
                            className={`h-9 rounded-md border text-xs font-medium transition-colors ${
                              isSelected
                                ? "bg-primary text-primary-foreground border-primary"
                                : "border-border bg-background hover:bg-muted hover:border-primary/30 text-foreground"
                            }`}
                          >
                            {timeLabel}
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* Meeting link */}
                <div className="space-y-1.5">
                  <Label className="text-xs flex items-center gap-1.5">
                    <Video className="h-3 w-3" />
                    Meeting Link <span className="text-muted-foreground font-normal">(optional)</span>
                  </Label>
                  <Input
                    value={meetingLink}
                    onChange={(e) => setMeetingLink(e.target.value)}
                    placeholder="https://meet.google.com/... or Zoom link"
                    className="h-9 text-sm"
                  />
                </div>

                {/* Notes */}
                <div className="space-y-1.5">
                  <Label className="text-xs">Notes <span className="text-muted-foreground font-normal">(optional)</span></Label>
                  <Textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="Interview notes, agenda, preparation tips..."
                    rows={3}
                    className="text-sm resize-none"
                  />
                </div>
              </>
            )}

            {/* Summary for booking link mode */}
            {sendBookingLink && (
              <div className="rounded-lg bg-muted/40 border border-border px-3 py-3 space-y-1.5">
                <p className="text-xs text-muted-foreground font-medium">What happens next</p>
                <ul className="text-xs text-muted-foreground space-y-1 list-disc list-inside">
                  <li>A personalized booking link is generated</li>
                  {candidateEmail ? (
                    <li>Link is emailed to <span className="font-medium text-foreground">{candidateEmail}</span></li>
                  ) : (
                    <li>You'll receive the link to share manually</li>
                  )}
                  <li>Candidate picks from your next 14 days of availability</li>
                  <li>Interview is auto-created when they confirm</li>
                </ul>
              </div>
            )}
          </div>
        </ScrollArea>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isBusy}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={isBusy} className="gap-1.5">
            {isBusy ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : sendBookingLink ? (
              <Mail className="h-3.5 w-3.5" />
            ) : (
              <Calendar className="h-3.5 w-3.5" />
            )}
            {isBusy
              ? "Processing..."
              : sendBookingLink
              ? candidateEmail
                ? "Send Booking Link"
                : "Generate Booking Link"
              : "Schedule Interview"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default ScheduleInterviewDialog;

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { toast } from "sonner";
import {
  Calendar,
  CheckCircle2,
  ChevronDown,
  Clock,
  ExternalLink,
  MoreHorizontal,
  Plus,
  UserX,
  XCircle,
} from "lucide-react";
import { format } from "date-fns";
import ScheduleInterviewDialog from "@/components/ScheduleInterviewDialog";

interface InterviewsPanelProps {
  resumeId: string;
  jobId: string;
  candidateName: string;
  candidateEmail?: string | null;
}

interface Interview {
  id: string;
  scheduled_at: string;
  duration_minutes: number;
  status: "scheduled" | "completed" | "cancelled" | "no_show";
  meeting_link: string | null;
  notes: string | null;
  interviewer_id: string;
  candidate_name: string;
}

const STATUS_CONFIG: Record<
  Interview["status"],
  { label: string; variant: "default" | "success" | "secondary" | "destructive" }
> = {
  scheduled: { label: "Scheduled", variant: "default" },
  completed: { label: "Completed", variant: "success" },
  cancelled: { label: "Cancelled", variant: "secondary" },
  no_show: { label: "No Show", variant: "destructive" },
};

const InterviewsPanel = ({
  resumeId,
  jobId,
  candidateName,
  candidateEmail,
}: InterviewsPanelProps) => {
  const queryClient = useQueryClient();
  const [scheduleOpen, setScheduleOpen] = useState(false);

  const { data: interviews, isLoading } = useQuery({
    queryKey: ["interviews", resumeId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("interviews")
        .select("id, scheduled_at, duration_minutes, status, meeting_link, notes, interviewer_id, candidate_name")
        .eq("resume_id", resumeId)
        .eq("job_id", jobId)
        .order("scheduled_at", { ascending: false });
      if (error) throw error;
      return (data ?? []) as Interview[];
    },
    staleTime: 30_000,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({
      interviewId,
      status,
    }: {
      interviewId: string;
      status: Interview["status"];
    }) => {
      const { error } = await (supabase as any)
        .from("interviews")
        .update({ status })
        .eq("id", interviewId);
      if (error) throw error;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["interviews", resumeId] });
      const label = STATUS_CONFIG[variables.status].label;
      toast.success(`Interview marked as ${label.toLowerCase()}`);
    },
    onError: () => {
      toast.error("Failed to update interview status");
    },
  });

  if (isLoading) {
    return (
      <div className="space-y-2">
        <Skeleton className="h-4 w-32" />
        <Skeleton className="h-20 w-full rounded-lg" />
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Section header */}
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-medium flex items-center gap-1.5">
          <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
          Interviews
          {(interviews?.length ?? 0) > 0 && (
            <span className="ml-1 text-[11px] bg-muted text-muted-foreground rounded-full px-1.5 py-0.5 font-normal">
              {interviews!.length}
            </span>
          )}
        </h4>
        <Button
          variant="outline"
          size="sm"
          className="h-7 gap-1 text-xs"
          onClick={() => setScheduleOpen(true)}
        >
          <Plus className="h-3 w-3" />
          Schedule
        </Button>
      </div>

      {/* Interview list */}
      {!interviews || interviews.length === 0 ? (
        <div className="rounded-lg border border-dashed border-border bg-muted/20 px-4 py-5 text-center">
          <Calendar className="h-6 w-6 text-muted-foreground/40 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">No interviews scheduled yet.</p>
          <Button
            variant="ghost"
            size="sm"
            className="mt-2 h-7 gap-1 text-xs"
            onClick={() => setScheduleOpen(true)}
          >
            <Plus className="h-3 w-3" />
            Schedule Interview
          </Button>
        </div>
      ) : (
        <div className="space-y-2">
          {interviews.map((iv) => {
            const cfg = STATUS_CONFIG[iv.status];
            const scheduledDate = new Date(iv.scheduled_at);
            const isPast = scheduledDate < new Date();

            return (
              <div
                key={iv.id}
                className="rounded-lg border border-border bg-background px-3 py-2.5 space-y-2"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium">
                        {format(scheduledDate, "EEE, MMM d · h:mm a")}
                      </span>
                      <Badge variant={cfg.variant} className="text-[10px] h-4 px-1.5">
                        {cfg.label}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-muted-foreground">
                      <Clock className="h-3 w-3" />
                      {iv.duration_minutes} min
                      {iv.meeting_link && (
                        <>
                          <span>·</span>
                          <a
                            href={iv.meeting_link}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-0.5 hover:text-foreground transition-colors"
                          >
                            <ExternalLink className="h-3 w-3" />
                            Join Meeting
                          </a>
                        </>
                      )}
                    </div>
                  </div>

                  {/* Status actions */}
                  {iv.status === "scheduled" && (
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0">
                          <MoreHorizontal className="h-3.5 w-3.5" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="text-sm">
                        <DropdownMenuItem
                          onClick={() =>
                            updateStatusMutation.mutate({ interviewId: iv.id, status: "completed" })
                          }
                          className="gap-2"
                        >
                          <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />
                          Mark Complete
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() =>
                            updateStatusMutation.mutate({ interviewId: iv.id, status: "no_show" })
                          }
                          className="gap-2"
                        >
                          <UserX className="h-3.5 w-3.5 text-orange-500" />
                          Mark No Show
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() =>
                            updateStatusMutation.mutate({ interviewId: iv.id, status: "cancelled" })
                          }
                          className="gap-2 text-destructive focus:text-destructive"
                        >
                          <XCircle className="h-3.5 w-3.5" />
                          Cancel
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  )}
                </div>

                {iv.notes && (
                  <p className="text-xs text-muted-foreground bg-muted/40 rounded px-2 py-1.5 border border-border">
                    {iv.notes}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}

      <ScheduleInterviewDialog
        open={scheduleOpen}
        onOpenChange={setScheduleOpen}
        jobId={jobId}
        resumeId={resumeId}
        candidateName={candidateName}
        candidateEmail={candidateEmail}
      />
    </div>
  );
};

export default InterviewsPanel;

import { useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, useMutation } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Calendar,
  CheckCircle2,
  Clock,
  Layers,
  Loader2,
  XCircle,
} from "lucide-react";
import { format } from "date-fns";

// ─── Types ───────────────────────────────────────────────────────────────────

interface SlotsData {
  job_title: string;
  candidate_name: string;
  duration_minutes: number;
  slots: string[];
  message?: string;
  error?: string;
}

type BookingState = "idle" | "selecting" | "confirming" | "success" | "error";

// ─── Helpers ─────────────────────────────────────────────────────────────────

function groupSlotsByDate(slots: string[]): Map<string, string[]> {
  const map = new Map<string, string[]>();
  for (const slot of slots) {
    const date = format(new Date(slot), "yyyy-MM-dd");
    if (!map.has(date)) map.set(date, []);
    map.get(date)!.push(slot);
  }
  return map;
}

// ─── Component ───────────────────────────────────────────────────────────────

const BookInterview = () => {
  const { token } = useParams<{ token: string }>();

  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);
  const [candidateName, setCandidateName] = useState<string>("");
  const [candidateEmail, setCandidateEmail] = useState<string>("");
  const [confirmedAt, setConfirmedAt] = useState<string | null>(null);

  // Fetch available slots from edge function
  const {
    data,
    isLoading,
    error: fetchError,
  } = useQuery<SlotsData>({
    queryKey: ["booking_slots", token],
    queryFn: async () => {
      const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;
      const res = await fetch(`${SUPABASE_URL}/functions/v1/book-interview?token=${token}`);
      if (!res.ok) {
        const body = await res.json().catch(() => ({ error: "Unknown error" }));
        throw new Error(body.error || `Request failed (${res.status})`);
      }
      return res.json() as Promise<SlotsData>;
    },
    enabled: !!token,
    retry: false,
    staleTime: Infinity,
  });

  // Confirm booking mutation
  const confirmMutation = useMutation({
    mutationFn: async () => {
      if (!selectedSlot || !token) throw new Error("Missing selection");

      const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;
      const res = await fetch(`${SUPABASE_URL}/functions/v1/book-interview`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token,
          selected_time: selectedSlot,
          candidate_name: candidateName.trim() || data?.candidate_name,
          candidate_email: candidateEmail.trim() || undefined,
        }),
      });

      if (!res.ok) {
        const body = await res.json().catch(() => ({ error: "Unknown error" }));
        throw new Error(body.error || `Failed (${res.status})`);
      }

      return res.json() as Promise<{ success: boolean; scheduled_at: string }>;
    },
    onSuccess: (result) => {
      setConfirmedAt(result.scheduled_at);
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to confirm booking");
    },
  });

  // ── Loading ──────────────────────────────────────────────────────────────

  if (isLoading) {
    return (
      <div className="min-h-svh bg-background flex flex-col">
        <BookHeader />
        <main className="flex-1 max-w-lg mx-auto w-full px-4 py-10 space-y-6">
          <Skeleton className="h-7 w-56" />
          <Skeleton className="h-4 w-40" />
          <div className="space-y-3">
            {[1, 2, 3].map((i) => <Skeleton key={i} className="h-24 w-full rounded-xl" />)}
          </div>
        </main>
      </div>
    );
  }

  // ── Error / Expired ──────────────────────────────────────────────────────

  if (fetchError || data?.error) {
    const msg = data?.error || (fetchError as Error)?.message || "Invalid link";
    return (
      <div className="min-h-svh bg-background flex flex-col">
        <BookHeader />
        <main className="flex-1 flex items-center justify-center px-4 py-10">
          <div className="text-center max-w-sm space-y-3">
            <div className="rounded-xl bg-muted/50 p-4 w-fit mx-auto">
              <XCircle className="h-8 w-8 text-destructive/60" />
            </div>
            <h2 className="text-lg font-semibold">Link unavailable</h2>
            <p className="text-sm text-muted-foreground">{msg}</p>
          </div>
        </main>
      </div>
    );
  }

  // ── Success ───────────────────────────────────────────────────────────────

  if (confirmedAt) {
    const confirmedDate = new Date(confirmedAt);
    return (
      <div className="min-h-svh bg-background flex flex-col">
        <BookHeader />
        <main className="flex-1 flex items-center justify-center px-4 py-10">
          <div className="text-center max-w-sm space-y-4">
            <div className="rounded-xl bg-green-50 dark:bg-green-950/40 p-4 w-fit mx-auto">
              <CheckCircle2 className="h-8 w-8 text-green-600" />
            </div>
            <div>
              <h2 className="text-xl font-semibold">Interview Scheduled</h2>
              <p className="text-sm text-muted-foreground mt-1">
                You're confirmed for an interview for{" "}
                <span className="font-medium text-foreground">{data?.job_title}</span>
              </p>
            </div>
            <div className="rounded-xl border border-border bg-muted/30 px-4 py-4 space-y-2 text-left">
              <div className="flex items-center gap-2 text-sm">
                <Calendar className="h-4 w-4 text-muted-foreground shrink-0" />
                <span className="font-medium">
                  {format(confirmedDate, "EEEE, MMMM d, yyyy")}
                </span>
              </div>
              <div className="flex items-center gap-2 text-sm">
                <Clock className="h-4 w-4 text-muted-foreground shrink-0" />
                <span>
                  {format(confirmedDate, "h:mm a")} · {data?.duration_minutes} minutes
                </span>
              </div>
            </div>
            <p className="text-xs text-muted-foreground">
              A confirmation has been sent to your email if provided.
            </p>
          </div>
        </main>
      </div>
    );
  }

  // ── Main booking UI ───────────────────────────────────────────────────────

  const slotsByDate = groupSlotsByDate(data?.slots ?? []);
  const hasSlots = (data?.slots?.length ?? 0) > 0;

  return (
    <div className="min-h-svh bg-background flex flex-col">
      <BookHeader />

      <main className="flex-1 max-w-lg mx-auto w-full px-4 py-10">
        {/* Title block */}
        <div className="mb-6 space-y-1">
          <h1 className="text-xl font-semibold">Schedule Your Interview</h1>
          <p className="text-sm text-muted-foreground">
            Role:{" "}
            <span className="font-medium text-foreground">{data?.job_title}</span>
          </p>
          <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <Clock className="h-3 w-3" />
            {data?.duration_minutes} minute interview
          </div>
        </div>

        {/* Candidate info */}
        <div className="mb-6 space-y-3 rounded-xl border border-border bg-muted/20 px-4 py-4">
          <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Your details</p>
          <div className="space-y-2">
            <div className="space-y-1">
              <Label className="text-xs">Name</Label>
              <Input
                value={candidateName}
                onChange={(e) => setCandidateName(e.target.value)}
                placeholder={data?.candidate_name || "Your name"}
                className="h-9 text-sm"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Email <span className="text-muted-foreground font-normal">(optional, for confirmation)</span></Label>
              <Input
                type="email"
                value={candidateEmail}
                onChange={(e) => setCandidateEmail(e.target.value)}
                placeholder="you@example.com"
                className="h-9 text-sm"
              />
            </div>
          </div>
        </div>

        {/* Time slots */}
        <div className="space-y-4">
          <h2 className="text-sm font-medium">Select a time</h2>

          {!hasSlots ? (
            <div className="rounded-xl border border-dashed border-border bg-muted/20 px-4 py-8 text-center">
              <Calendar className="h-7 w-7 text-muted-foreground/40 mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">
                {data?.message || "No available slots for the next 14 days."}
              </p>
            </div>
          ) : (
            Array.from(slotsByDate.entries()).map(([date, slots]) => (
              <div key={date} className="space-y-2">
                <p className="text-xs font-medium text-muted-foreground">
                  {format(new Date(date + "T00:00:00"), "EEEE, MMMM d")}
                </p>
                <div className="grid grid-cols-3 gap-2">
                  {slots.map((slot) => {
                    const slotDate = new Date(slot);
                    const timeLabel = format(slotDate, "h:mm a");
                    const isSelected = selectedSlot === slot;
                    return (
                      <button
                        key={slot}
                        type="button"
                        onClick={() => setSelectedSlot(slot)}
                        className={`h-10 rounded-lg border text-sm font-medium transition-colors ${
                          isSelected
                            ? "bg-primary text-primary-foreground border-primary shadow-sm"
                            : "border-border bg-background hover:bg-muted text-foreground"
                        }`}
                      >
                        {timeLabel}
                      </button>
                    );
                  })}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Confirm button */}
        {selectedSlot && (
          <div className="mt-6 space-y-3">
            <div className="rounded-xl border border-primary/20 bg-primary/5 px-4 py-3 flex items-center gap-3">
              <Calendar className="h-4 w-4 text-primary shrink-0" />
              <div className="text-sm">
                <span className="font-medium">
                  {format(new Date(selectedSlot), "EEEE, MMMM d")}
                </span>
                {" at "}
                <span className="font-medium">{format(new Date(selectedSlot), "h:mm a")}</span>
                <span className="text-muted-foreground"> · {data?.duration_minutes} min</span>
              </div>
            </div>

            <Button
              className="w-full gap-2"
              onClick={() => confirmMutation.mutate()}
              disabled={confirmMutation.isPending}
            >
              {confirmMutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <CheckCircle2 className="h-4 w-4" />
              )}
              {confirmMutation.isPending ? "Confirming..." : "Confirm Interview"}
            </Button>
          </div>
        )}
      </main>
    </div>
  );
};

function BookHeader() {
  return (
    <header className="border-b border-border bg-background/95 backdrop-blur">
      <div className="max-w-lg mx-auto px-4 py-4 flex items-center gap-2">
        <div className="h-7 w-7 rounded bg-primary/10 flex items-center justify-center">
          <Layers className="h-3.5 w-3.5 text-primary" />
        </div>
        <span className="text-sm font-semibold">Rankora</span>
      </div>
    </header>
  );
}

export default BookInterview;

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import {
  CheckCircle2,
  Copy,
  ExternalLink,
  Facebook,
  Linkedin,
  QrCode,
  Share2,
  Twitter,
  XCircle,
  Rss,
} from "lucide-react";

interface JobDistributionPanelProps {
  jobId: string;
  jobTitle: string;
  slug?: string | null;
  teamId?: string | null;
  careerPageActive?: boolean;
}

// ─── Simple QR Code (SVG-based, no npm package) ──────────────────────────────
// Uses the free qr.io API or falls back to a Google Charts-compatible URL.
function QrCodeImage({ url }: { url: string }) {
  const qrSrc = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(url)}&size=160x160&format=png&margin=4`;
  return (
    <img
      src={qrSrc}
      alt="QR Code"
      width={160}
      height={160}
      className="rounded-lg border border-border"
      loading="lazy"
    />
  );
}

const JobDistributionPanel = ({
  jobId,
  jobTitle,
  slug,
  teamId,
  careerPageActive = false,
}: JobDistributionPanelProps) => {
  const [showQr, setShowQr] = useState(false);

  // Build URLs
  const APP_URL = import.meta.env.VITE_APP_URL || window.location.origin;
  const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;

  const jobUrl = slug ? `${APP_URL}/careers/${slug}/jobs/${jobId}` : null;
  const indeedFeedUrl = teamId
    ? `${SUPABASE_URL}/functions/v1/indeed-feed?team_id=${teamId}`
    : null;

  // Check whether career page has JSON-LD (i.e., career page is configured)
  const hasCareerPage = careerPageActive && !!slug;

  // Share text
  const shareText = `We're hiring! ${jobTitle}${jobUrl ? ` → ${jobUrl}` : ""}`;

  const handleCopy = (text: string, label: string) => {
    navigator.clipboard.writeText(text).then(() => {
      toast.success(`${label} copied`);
    });
  };

  const openShare = (platform: "linkedin" | "twitter" | "facebook") => {
    if (!jobUrl) {
      toast.error("Enable your career page first to get a shareable job URL");
      return;
    }
    const encodedUrl = encodeURIComponent(jobUrl);
    const encodedText = encodeURIComponent(shareText);

    const urls: Record<string, string> = {
      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`,
      twitter: `https://twitter.com/intent/tweet?text=${encodedText}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
    };

    window.open(urls[platform], "_blank", "noopener,noreferrer,width=600,height=500");
  };

  return (
    <div className="space-y-4">
      {/* Google Jobs */}
      <DistributionRow
        icon={
          <div className="h-7 w-7 rounded bg-blue-50 dark:bg-blue-950/40 flex items-center justify-center shrink-0">
            <span className="text-xs font-bold text-blue-600">G</span>
          </div>
        }
        title="Google Jobs"
        description="Structured data (JSON-LD) enables Google to index your job postings"
        status={hasCareerPage ? "active" : "inactive"}
        statusLabel={hasCareerPage ? "Active" : "No career page"}
        actions={
          hasCareerPage ? (
            <Button
              variant="outline"
              size="sm"
              className="h-7 gap-1 text-xs"
              onClick={() =>
                window.open(
                  `https://search.google.com/test/rich-results?url=${encodeURIComponent(jobUrl!)}`,
                  "_blank",
                  "noopener,noreferrer"
                )
              }
            >
              <ExternalLink className="h-3 w-3" />
              Test in Google
            </Button>
          ) : null
        }
      />

      {/* Indeed */}
      <DistributionRow
        icon={
          <div className="h-7 w-7 rounded bg-[#003A9B]/10 flex items-center justify-center shrink-0">
            <span className="text-[10px] font-bold text-[#003A9B] dark:text-blue-400">INDEED</span>
          </div>
        }
        title="Indeed"
        description="Submit the XML feed URL to Indeed's publisher program. Feed auto-updates with published jobs."
        status={indeedFeedUrl ? "active" : "inactive"}
        statusLabel={indeedFeedUrl ? "Feed ready" : "No team configured"}
        actions={
          indeedFeedUrl ? (
            <div className="flex items-center gap-2">
              <code className="text-[10px] text-muted-foreground truncate max-w-[200px] font-mono">
                {indeedFeedUrl}
              </code>
              <Button
                variant="outline"
                size="sm"
                className="h-7 gap-1 text-xs shrink-0"
                onClick={() => handleCopy(indeedFeedUrl, "Indeed feed URL")}
              >
                <Copy className="h-3 w-3" />
                Copy
              </Button>
            </div>
          ) : null
        }
      />

      {/* LinkedIn */}
      <DistributionRow
        icon={
          <div className="h-7 w-7 rounded bg-[#0A66C2]/10 flex items-center justify-center shrink-0">
            <Linkedin className="h-3.5 w-3.5 text-[#0A66C2]" />
          </div>
        }
        title="LinkedIn"
        description="Share as a post with rich preview. Candidates see title, company, and apply link."
        status={jobUrl ? "active" : "inactive"}
        statusLabel={jobUrl ? "Ready" : "Need career page"}
        actions={
          <Button
            variant="outline"
            size="sm"
            className="h-7 gap-1 text-xs border-[#0A66C2]/30 text-[#0A66C2] hover:bg-[#0A66C2]/10"
            onClick={() => openShare("linkedin")}
          >
            <Share2 className="h-3 w-3" />
            Share on LinkedIn
          </Button>
        }
      />

      {/* Twitter/X */}
      <DistributionRow
        icon={
          <div className="h-7 w-7 rounded bg-foreground/5 flex items-center justify-center shrink-0">
            <Twitter className="h-3.5 w-3.5 text-foreground" />
          </div>
        }
        title="X (Twitter)"
        description="Post a tweet with job title and direct link."
        status={jobUrl ? "active" : "inactive"}
        statusLabel={jobUrl ? "Ready" : "Need career page"}
        actions={
          <Button
            variant="outline"
            size="sm"
            className="h-7 gap-1 text-xs"
            onClick={() => openShare("twitter")}
          >
            <Share2 className="h-3 w-3" />
            Share on X
          </Button>
        }
      />

      {/* Facebook */}
      <DistributionRow
        icon={
          <div className="h-7 w-7 rounded bg-[#1877F2]/10 flex items-center justify-center shrink-0">
            <Facebook className="h-3.5 w-3.5 text-[#1877F2]" />
          </div>
        }
        title="Facebook"
        description="Share the job to your Facebook page or group."
        status={jobUrl ? "active" : "inactive"}
        statusLabel={jobUrl ? "Ready" : "Need career page"}
        actions={
          <Button
            variant="outline"
            size="sm"
            className="h-7 gap-1 text-xs border-[#1877F2]/30 text-[#1877F2] hover:bg-[#1877F2]/10"
            onClick={() => openShare("facebook")}
          >
            <Share2 className="h-3 w-3" />
            Share on Facebook
          </Button>
        }
      />

      {/* Job link + QR */}
      <div className="rounded-xl border border-border bg-muted/20 p-4 space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-sm font-medium flex items-center gap-1.5">
            <Share2 className="h-3.5 w-3.5 text-muted-foreground" />
            Direct Job Link
          </h4>
        </div>

        {jobUrl ? (
          <div className="flex items-center gap-2">
            <code className="text-xs text-muted-foreground font-mono truncate flex-1 bg-background rounded border border-border px-2 py-1.5">
              {jobUrl}
            </code>
            <Button
              variant="outline"
              size="sm"
              className="h-8 gap-1 text-xs shrink-0"
              onClick={() => handleCopy(jobUrl, "Job URL")}
            >
              <Copy className="h-3 w-3" />
              Copy
            </Button>
          </div>
        ) : (
          <p className="text-xs text-muted-foreground">
            Enable your career page to get a shareable job URL.
          </p>
        )}

        {/* QR toggle */}
        {jobUrl && (
          <div className="space-y-2">
            <Button
              variant="ghost"
              size="sm"
              className="h-7 gap-1.5 text-xs text-muted-foreground hover:text-foreground"
              onClick={() => setShowQr((v) => !v)}
            >
              <QrCode className="h-3.5 w-3.5" />
              {showQr ? "Hide" : "Show"} QR Code
            </Button>

            {showQr && (
              <div className="flex flex-col items-start gap-2">
                <QrCodeImage url={jobUrl} />
                <p className="text-xs text-muted-foreground">
                  Right-click to save — useful for job fairs and printed materials.
                </p>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Setup prompt when career page not active */}
      {!hasCareerPage && (
        <div className="rounded-xl border border-dashed border-border bg-muted/10 px-4 py-4 text-center">
          <Rss className="h-5 w-5 text-muted-foreground/40 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">
            Set up your career page to unlock social sharing, job links, and the Indeed XML feed.
          </p>
          <Button variant="outline" size="sm" className="mt-2 h-7 text-xs" asChild>
            <a href="/career-settings">Configure Career Page</a>
          </Button>
        </div>
      )}
    </div>
  );
};

// ─── Row sub-component ────────────────────────────────────────────────────────

function DistributionRow({
  icon,
  title,
  description,
  status,
  statusLabel,
  actions,
}: {
  icon: React.ReactNode;
  title: string;
  description: string;
  status: "active" | "inactive";
  statusLabel: string;
  actions?: React.ReactNode | null;
}) {
  return (
    <div className="rounded-xl border border-border bg-background p-4 space-y-2">
      <div className="flex items-start gap-3">
        {icon}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-medium">{title}</span>
            <Badge
              variant={status === "active" ? "success" : "secondary"}
              className="text-[10px] h-4 px-1.5"
            >
              {status === "active" ? (
                <CheckCircle2 className="h-2.5 w-2.5 mr-0.5" />
              ) : (
                <XCircle className="h-2.5 w-2.5 mr-0.5" />
              )}
              {statusLabel}
            </Badge>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">{description}</p>
        </div>
      </div>
      {actions && <div className="pl-10">{actions}</div>}
    </div>
  );
}

export default JobDistributionPanel;

